 (791), (1171), (734), (298546), (88286), (606), (558), (68738), (197688), (77726), (1603), (90895), (79819), (227), (212), (197681), (756), (95184), (722), (74132), (1244), (445), (1049), (757), (82467), (1422), (206), (65769), (304429), (983), (286), (773), (771), (254), (216190), (1013), (82554), (260317), (446), (205), (81930), (215221), (750), (204216), (201003), (65954), (93115), (92578), (1285), (74694), (204429), (84913), (204362), (198236), (202764), (1045), (289877), (76140), (86882), (71261), (166) ) AS t(id) ), tier_category AS ( SELECT DISTINCT source_location_id, destination_location_id, CASE WHEN source_location_id IN (SELECT id FROM leisure) OR destination_location_id IN (SELECT id FROM leisure) THEN 'Leisure' WHEN source_location_id IN (SELECT id FROM pilgrim) OR destination_location_id IN (SELECT id FROM pilgrim) THEN 'Pilgrim' WHEN source_location_id IN (SELECT id FROM tier_1) AND destination_location_id IN (SELECT id FROM tier_1) THEN 'Tier1 - Tier1' WHEN source_location_id IN (SELECT id FROM tier_1) AND destination_location_id IN (SELECT id FROM tier_2) THEN 'Tier1 - Tier2' WHEN source_location_id IN (SELECT id FROM tier_1) AND destination_location_id NOT IN ( SELECT id FROM tier_1 UNION ALL SELECT id FROM tier_2 UNION ALL SELECT id FROM pilgrim UNION ALL SELECT id FROM leisure ) THEN 'Tier1 - Tier3' WHEN source_location_id IN (SELECT id FROM tier_2) AND destination_location_id IN (SELECT id FROM tier_1) THEN 'Tier2 - Tier1' WHEN source_location_id IN (SELECT id FROM tier_2) AND destination_location_id IN (SELECT id FROM tier_2) THEN 'Tier2 - Tier2' WHEN source_location_id IN (SELECT id FROM tier_2) AND destination_location_id NOT IN ( SELECT id FROM tier_1 UNION ALL SELECT id FROM tier_2 UNION ALL SELECT id FROM pilgrim UNION ALL SELECT id FROM leisure ) THEN 'Tier2 - Tier3' WHEN source_location_id NOT IN ( SELECT id FROM tier_1 UNION ALL SELECT id FROM tier_2 UNION ALL SELECT id FROM pilgrim UNION ALL SELECT id FROM leisure ) AND destination_location_id IN (SELECT id FROM tier_1) THEN 'Tier3 - Tier1' WHEN source_location_id NOT IN ( SELECT id FROM tier_1 UNION ALL SELECT id FROM tier_2 UNION ALL SELECT id FROM pilgrim UNION ALL SELECT id FROM leisure ) AND destination_location_id IN (SELECT id FROM tier_2) THEN 'Tier3 - Tier2' WHEN source_location_id NOT IN ( SELECT id FROM tier_1 UNION ALL SELECT id FROM tier_2 UNION ALL SELECT id FROM pilgrim UNION ALL SELECT id FROM leisure ) AND destination_location_id NOT IN ( SELECT id FROM tier_1 UNION ALL SELECT id FROM tier_2 UNION ALL SELECT id FROM pilgrim UNION ALL SELECT id FROM leisure ) THEN 'Tier3 - Tier3' ELSE 'Uncategorized' END AS route_category FROM "transaction"."bus_ticket_events" WHERE 1 = 1 AND date_of_issue >= TIMESTAMP '2025-11-30 18:30:00' AND date_of_issue < TIMESTAMP '2025-12-31 18:30:00' AND event_type = 101 AND event_class = 2 AND country_code = 'IND' AND sales_channel IN ('RB:MOBILEWEB#droidapp', 'DROIDAPP') ) SELECT tc.route_category, -- CASE WHEN date_diff('day', n.date_of_issue, n.date_of_journey) = 0 THEN '0. Same Day' -- WHEN date_diff('day', n.date_of_issue, n.date_of_journey) = 1 THEN '1. Next Day' -- WHEN date_diff('day', n.date_of_issue, n.date_of_journey) = 2 THEN '2. DBD 2' -- WHEN date_diff('day', n.date_of_issue, n.date_of_journey) > 2 THEN '3. DBD 2+' -- ELSE 'NA' END AS dbd, -- UPPER(n.user_type) user_type, 'Overall' AS user_type, COUNT(DISTINCT n.tin) AS txn_count, COUNT(DISTINCT CASE WHEN n.is_reschedulable = True THEN n.tin END) AS reschedulable_txn_count, COUNT(DISTINCT CASE WHEN n.is_free_bus = True THEN n.tin END) AS free_bus_changeable_tins, COUNT(DISTINCT CASE WHEN bc.order_uuid IS NOT NULL THEN n.tin END) AS cancelled_txn_count, COUNT(DISTINCT CASE WHEN n.rescheduling_for IS NOT NULL THEN n.tin END) AS rescheduled_txn_count, COUNT(DISTINCT CASE WHEN n.rescheduling_for IS NOT NULL AND bc.order_uuid IS NOT NULL THEN n.tin END) AS rescheduled_and_cancelled_txn_count, COUNT(DISTINCT CASE WHEN n.reschedule_charge > 0 AND n.rescheduling_for IS NOT NULL THEN n.tin END) AS rescheduled_txns_by_paying_more, COUNT(DISTINCT CASE WHEN bc.cancellation_reason = 'RESCHEDULED' AND n.is_free_bus = True THEN n.tin END) AS free_bus_changed_tins FROM "transaction"."bus_cancellation_events" n LEFT JOIN tier_category tc ON tc.source_location_id = n.source_location_id AND tc.destination_location_id = n.destination_location_id LEFT JOIN "transaction"."bus_cancellation_events" bc ON n.order_uuid = bc.order_uuid WHERE 1 = 1 AND n.date_of_issue >= TIMESTAMP '2025-11-30 18:30:00' AND n.date_of_issue < TIMESTAMP '2025-12-31 18:30:00' AND n.event_type = 101 AND n.event_class = 2 AND n.country_code = 'IND' AND n.sales_channel IN ('RB:MOBILEWEB#droidapp', 'DROIDAPP') GROUP BY 1, 2 -- , 3 ORDER BY 1, 2 DESC
